    values ('cand_10', 't_americana', 'job_motos', 'vendedor', 'u_jessica', (current_date - 15)::text::date, 'done', '{"V1":"\"Le pregunté para qué usaría la moto y le ofrecí dos opciones de crédito; regresó a comprar el casco.\"","V9":"\"Cerré el trimestre al 118 % de mi meta personal.\"","story":"Buscaba refrigeradora para negocio; le preguntó volumen y horario, ofreció modelo comercial. Venta + garantía extendida."}'::jsonb, '{"V1":5,"V2":4,"V3":4,"V4":5,"V5":4,"V6":4,"V7":4,"V8":5,"V9":5,"V10":4}'::jsonb, '{}'::jsonb, 'main', '{"cliente":5,"comunicacion":4,"problemas":4,"resultados":5}'::jsonb, '{"M1":"B","M2":"C","M3":"B","M4":"A","M5":"C"}'::jsonb, '{"cliente":"Escucha antes de ofrecer y da seguimiento posventa por iniciativa propia.","comunicacion":"Explica crédito y garantías con palabras sencillas; confirma que el cliente entendió.","equipo":"Apoya a compañeros nuevos con el sistema de crédito.","problemas":"Prioriza al cliente en hora pico y pide apoyo a tiempo.","resultados":"Da cifras propias: 118 % de su meta en el trimestre."}'::jsonb, now() - interval '15 days');
